import Foundation
import os

/// 텍스트 클립보드 양방향 공유. 로컬 클립보드 변경을 폴링해 피어에 보내고, 받은 텍스트를 클립보드에 쓴다.
/// 원격 세션 중에만 동작한다(세션 게이트는 입력 동기화와 같다). 에코 억제는 `changeCount` 기준이다.
///
/// 스레드: 메인 스레드 전용 (PeerManager와 같다).
public final class ClipboardSyncController {
    /// 보낼 수 있는 텍스트 상한(UTF-8 바이트).
    public static let maxTextBytes = 256 * 1024

    /// 비밀번호 관리자 등이 "공유하지 말 것"으로 표시하는 타입 (nspasteboard.org).
    static let concealedTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
    ]

    public enum SkipReason: Equatable {
        case noSession        // 원격 세션 아님
        case tooLarge         // 상한 초과
        case concealed        // 숨김·임시·자동 생성 항목
        case peerNeedsUpdate  // 연결된 피어가 클립보드 기능을 알리지 않음
    }

    /// 마지막 공유 상태. 메뉴 표시용.
    public enum Status: Equatable {
        case none
        case sent
        case received
        case skipped(SkipReason)
    }

    /// 연결된 피어의 클립보드 기능 지원 여부.
    public enum PeerSupport: Equatable {
        case noPeers
        case supported     // 하나 이상 지원
        case needsUpdate   // 연결된 피어가 모두 예전 버전
    }

    static let log = Logger(subsystem: "com.jeongsk.VNCAutoResolution", category: "clipboard")

    public private(set) var lastStatus: Status = .none
    /// 상태가 바뀔 때마다 불린다.
    public var onChange: (() -> Void)?

    private let clipboard: ClipboardAccessing
    private let settings: ClipboardSettingsStoring
    private let peers: PeerManager
    private let inputSync: InputSyncController

    /// 이미 처리한(보냈거나, 건너뛰었거나, 받아서 쓴) 클립보드의 `changeCount`.
    /// 시작할 때의 값으로 시작해, 앱이 켜지기 전에 복사해 둔 내용은 보내지 않는다.
    private var seenChangeCount: Int

    public init(
        clipboard: ClipboardAccessing,
        settings: ClipboardSettingsStoring,
        peers: PeerManager,
        inputSync: InputSyncController
    ) {
        self.clipboard = clipboard
        self.settings = settings
        self.peers = peers
        self.inputSync = inputSync
        self.seenChangeCount = clipboard.changeCount
    }

    // MARK: 상태

    public var enabled: Bool {
        get { settings.clipboardSyncEnabled }
        set {
            // 켜기 전에 복사해 둔 내용은 보내지 않는다.
            seenChangeCount = clipboard.changeCount
            settings.clipboardSyncEnabled = newValue
            onChange?()
        }
    }

    public var peerSupport: PeerSupport {
        let connected = peers.peers
        if connected.isEmpty { return .noPeers }
        return connected.contains(where: Self.supportsClipboard) ? .supported : .needsUpdate
    }

    // MARK: 이벤트

    /// 클립보드 `changeCount`를 확인한다. 앱이 짧은 주기로 부른다.
    /// 꺼져 있거나 세션이 없을 때도 기준값은 갱신해, 그 사이에 복사한 내용이 나중에 보내지지 않게 한다.
    public func poll() {
        let count = clipboard.changeCount
        guard count != seenChangeCount else { return }
        seenChangeCount = count
        guard enabled else { return }
        let item = clipboard.read()
        guard let text = item.text, !text.isEmpty else { return }   // 텍스트가 아닌 항목은 다루지 않는다.

        if item.types.contains(where: Self.concealedTypes.contains) { return skip(.concealed) }
        if text.utf8.count > Self.maxTextBytes { return skip(.tooLarge) }
        guard inputSync.isRemoteSessionActive else { return skip(.noSession) }
        switch peerSupport {
        case .noPeers: return
        case .needsUpdate: return skip(.peerNeedsUpdate)
        case .supported: break
        }

        Self.log.debug("send: \(text.utf8.count, privacy: .public)바이트")
        peers.broadcast(.clipboard(deviceID: peers.deviceID, text: text), where: Self.supportsClipboard)
        setStatus(.sent)
    }

    /// 피어가 보낸 메시지(hello 이후 검증된 것)를 처리한다.
    public func handle(_ message: PeerMessage, from peer: PeerManager.Peer) {
        guard case .clipboard(_, let text) = message else { return }
        guard enabled, inputSync.isRemoteSessionActive else {
            Self.log.debug("recv: 공유 조건 아님")
            return
        }
        guard text.utf8.count <= Self.maxTextBytes else { return }
        Self.log.debug("recv: \(text.utf8.count, privacy: .public)바이트 적용")
        clipboard.write(text: text)
        // 방금 쓴 내용이 다시 보내지지 않도록 쓴 뒤의 값을 기준으로 삼는다(+1이라고 가정하지 않는다).
        seenChangeCount = clipboard.changeCount
        setStatus(.received)
    }

    // MARK: 내부

    private static func supportsClipboard(_ peer: PeerManager.Peer) -> Bool {
        peer.features.contains(PeerFeature.clipboard)
    }

    private func skip(_ reason: SkipReason) {
        Self.log.debug("skip: \(String(describing: reason), privacy: .public)")
        setStatus(.skipped(reason))
    }

    private func setStatus(_ status: Status) {
        lastStatus = status
        onChange?()
    }
}
